unicorn_colossus.source:
export const envelope = [26, 44, 26];

export default function build(api) {
  const [W, H, D] = envelope;
  const grid = new Map();

  // Palette selection: harmonize with the unicorn realm's pristine masonry
  const T_STONE = api.theme?.stone?.primary || "minecraft:smooth_quartz";
  const T_ACCENT = api.theme?.stone?.accent || "minecraft:quartz_pillar[axis=y]";
  const T_STAIRS = api.theme?.stone?.stairs || "minecraft:smooth_quartz_stairs";
  const T_SLAB = api.theme?.stone?.slab || "minecraft:smooth_quartz_slab";
  const T_WALL = api.theme?.stone?.wall || "minecraft:diorite_wall";
  const T_PLINTH = api.theme?.ground?.plinth || "minecraft:quartz_bricks";
  const T_PAVE = api.theme?.ground?.pavement || "minecraft:smooth_quartz";
  const T_REVE = api.theme?.ground?.revetment || "minecraft:quartz_block";

  // Arcane / celestial materials
  const M_CRYSTAL = "minecraft:amethyst_block";
  const M_LANTERN = "minecraft:sea_lantern";
  const M_GOLD = "minecraft:gold_block";
  const M_LAPIS = "minecraft:lapis_block";
  const M_ROD_NORTH = "minecraft:end_rod[facing=north]";
  const M_ROD_UP = "minecraft:end_rod[facing=up]";
  const M_CLUSTER_UP = "minecraft:amethyst_cluster[facing=up]";

  function setBlock(x, y, z, block) {
    const ix = Math.round(x);
    const iy = Math.round(y);
    const iz = Math.round(z);
    if (ix >= 0 && ix < W && iy >= 0 && iy < H && iz >= 0 && iz < D) {
      grid.set((ix << 16) | (iy << 8) | iz, block);
    }
  }

  function getBlock(x, y, z) {
    const ix = Math.round(x);
    const iy = Math.round(y);
    const iz = Math.round(z);
    if (ix >= 0 && ix < W && iy >= 0 && iy < H && iz >= 0 && iz < D) {
      return grid.get((ix << 16) | (iy << 8) | iz) || null;
    }
    return null;
  }

  function fillEllipsoid(cx, cy, cz, rx, ry, rz, block, replace = true) {
    const minX = Math.max(0, Math.floor(cx - rx));
    const maxX = Math.min(W - 1, Math.ceil(cx + rx));
    const minY = Math.max(0, Math.floor(cy - ry));
    const maxY = Math.min(H - 1, Math.ceil(cy + ry));
    const minZ = Math.max(0, Math.floor(cz - rz));
    const maxZ = Math.min(D - 1, Math.ceil(cz + rz));

    for (let x = minX; x <= maxX; x++) {
      const dx = (x - cx) / rx;
      for (let y = minY; y <= maxY; y++) {
        const dy = (y - cy) / ry;
        for (let z = minZ; z <= maxZ; z++) {
          const dz = (z - cz) / rz;
          if (dx * dx + dy * dy + dz * dz <= 1.0) {
            if (replace || !getBlock(x, y, z)) {
              setBlock(x, y, z, block);
            }
          }
        }
      }
    }
  }

  function fillCapsule(x0, y0, z0, x1, y1, z1, r0, r1, block, replace = true) {
    const dx = x1 - x0;
    const dy = y1 - y0;
    const dz = z1 - z0;
    const len = Math.hypot(dx, dy, dz);
    const steps = Math.max(1, Math.ceil(len * 2.5));
    for (let i = 0; i <= steps; i++) {
      const t = i / steps;
      const cx = x0 + dx * t;
      const cy = y0 + dy * t;
      const cz = z0 + dz * t;
      const r = r0 + (r1 - r0) * t;
      fillEllipsoid(cx, cy, cz, r, r, r, block, replace);
    }
  }

  function fillCurve(points, radii, block, replace = true) {
    for (let i = 0; i < points.length - 1; i++) {
      const p0 = points[i];
      const p1 = points[i + 1];
      const r0 = Array.isArray(radii) ? radii[i] : radii;
      const r1 = Array.isArray(radii) ? radii[i + 1] : radii;
      fillCapsule(p0.x, p0.y, p0.z, p1.x, p1.y, p1.z, r0, r1, block, replace);
    }
  }

  function fillQuad(p00, p10, p11, p01, block, thickness = 0.85) {
    const uSteps = 8;
    const vSteps = 8;
    for (let u = 0; u <= uSteps; u++) {
      const tu = u / uSteps;
      for (let v = 0; v <= vSteps; v++) {
        const tv = v / vSteps;
        const x = (1 - tu) * (1 - tv) * p00.x + tu * (1 - tv) * p10.x + tu * tv * p11.x + (1 - tu) * tv * p01.x;
        const y = (1 - tu) * (1 - tv) * p00.y + tu * (1 - tv) * p10.y + tu * tv * p11.y + (1 - tu) * tv * p01.y;
        const z = (1 - tu) * (1 - tv) * p00.z + tu * (1 - tv) * p10.z + tu * tv * p11.z + (1 - tu) * tv * p01.z;
        fillEllipsoid(x, y, z, thickness, thickness, thickness, block, false);
      }
    }
  }

  function inOctagon(x, z, r) {
    const dx = Math.abs(x - 12.5);
    const dz = Math.abs(z - 12.5);
    return dx <= r && dz <= r && (dx + dz) <= r * 1.38;
  }

  // ==========================================
  // 1. STEPPED RUNIC PLINTH & GROUND FOOTING
  // ==========================================
  const seatPlaneY = 4;

  // Tier 0 & Foundation
  for (let x = 0; x < W; x++) {
    for (let z = 0; z < D; z++) {
      if (inOctagon(x, z, 10.5)) {
        const groundH = api.heightAt(x, z);
        const gy = Math.max(0, Math.min(seatPlaneY, seatPlaneY + Math.round(groundH)));
        for (let y = gy; y <= seatPlaneY; y++) {
          setBlock(x, y, z, inOctagon(x, z, 9.5) ? T_PLINTH : T_REVE);
        }
      }
    }
  }

  // Tier 1 (Y = 5)
  for (let x = 0; x < W; x++) {
    for (let z = 0; z < D; z++) {
      if (inOctagon(x, z, 9.5)) {
        const isBorder = !inOctagon(x, z, 8.5);
        setBlock(x, 5, z, isBorder ? T_ACCENT : T_STONE);
      }
    }
  }

  // Tier 2 (Y = 6) - Inlaid Arcane Ward Circle pointing North (-Z)
  for (let x = 0; x < W; x++) {
    for (let z = 0; z < D; z++) {
      if (inOctagon(x, z, 8.5)) {
        const d = Math.hypot(x - 12.5, z - 12.5);
        const isNorthLeyline = Math.abs(x - 12.5) <= 1.0 && z <= 12.5;
        const isRuneRing = d >= 6.2 && d <= 7.6;
        const isCardinal = (Math.abs(x - 12.5) <= 0.8 && (z <= 5.5 || z >= 19.5)) ||
                           (Math.abs(z - 12.5) <= 0.8 && (x <= 5.5 || x >= 19.5));

        if (isNorthLeyline || isCardinal) {
          setBlock(x, 6, z, M_LANTERN);
        } else if (isRuneRing) {
          setBlock(x, 6, z, (Math.floor(d * 3) % 2 === 0) ? M_CRYSTAL : M_LAPIS);
        } else {
          setBlock(x, 6, z, inOctagon(x, z, 7.5) ? T_PAVE : T_STONE);
        }
      }
    }
  }

  // Tier 3 (Y = 7) - High Pedestal Platform
  for (let x = 0; x < W; x++) {
    for (let z = 0; z < D; z++) {
      if (inOctagon(x, z, 7.5)) {
        setBlock(x, 7, z, inOctagon(x, z, 6.5) ? T_STONE : T_ACCENT);
      }
    }
  }

  // Plinth Pylons & Ward Beacons (4 Corners)
  const pylonPositions = [
    { x: 6, z: 6 },
    { x: 19, z: 6 },
    { x: 6, z: 19 },
    { x: 19, z: 19 }
  ];
  for (const p of pylonPositions) {
    setBlock(p.x, 7, p.z, T_ACCENT);
    setBlock(p.x, 8, p.z, T_WALL);
    setBlock(p.x, 9, p.z, M_CRYSTAL);
    setBlock(p.x, 10, p.z, M_LANTERN);
    setBlock(p.x, 11, p.z, M_CLUSTER_UP);
  }

  // ==========================================
  // 2. REARING HIND LEGS & GILDED HOOVES
  // ==========================================
  // Left Hind Hoof & Leg (planted at Z = 16)
  fillCapsule(8.5, 7.5, 16.0, 8.5, 9.5, 16.0, 1.4, 1.3, M_GOLD);
  fillCapsule(8.5, 9.5, 16.0, 8.5, 13.5, 17.5, 1.3, 1.4, T_STONE);
  fillCapsule(8.5, 13.5, 17.5, 9.5, 19.5, 15.0, 1.4, 2.2, T_STONE);

  // Right Hind Hoof & Leg (planted at Z = 16)
  fillCapsule(16.5, 7.5, 16.0, 16.5, 9.5, 16.0, 1.4, 1.3, M_GOLD);
  fillCapsule(16.5, 9.5, 16.0, 16.5, 13.5, 17.5, 1.3, 1.4, T_STONE);
  fillCapsule(16.5, 13.5, 17.5, 15.5, 19.5, 15.0, 1.4, 2.2, T_STONE);

  // ==========================================
  // 3. PELVIS, HAUNCHES & BILLOWING TAIL
  // ==========================================
  fillEllipsoid(12.5, 19.5, 15.0, 3.3, 2.9, 3.1, T_STONE);
  fillEllipsoid(9.8, 19.0, 15.3, 2.2, 2.4, 2.2, T_STONE);
  fillEllipsoid(15.2, 19.0, 15.3, 2.2, 2.4, 2.2, T_STONE);

  // Billowing Arcane Tail sweeping down to merge with plinth
  const tailPoints = [
    { x: 12.5, y: 21.0, z: 17.5 },
    { x: 12.5, y: 18.5, z: 19.5 },
    { x: 13.5, y: 15.0, z: 20.8 },
    { x: 12.0, y: 11.5, z: 20.5 },
    { x: 11.0, y: 8.5, z: 19.0 },
    { x: 12.0, y: 7.5, z: 17.5 }
  ];
  fillCurve(tailPoints, [1.6, 1.8, 1.9, 1.8, 1.6, 1.5], T_STONE);

  // Crystal plumes on tail
  fillCapsule(13.5, 15.0, 20.8, 15.0, 13.0, 21.2, 1.1, 0.7, M_CRYSTAL);
  fillCapsule(12.0, 11.5, 20.5, 10.0, 9.5, 20.0, 1.0, 0.6, M_LANTERN);
  fillCapsule(11.0, 8.5, 19.0, 13.0, 7.5, 20.5, 1.2, 0.8, M_CRYSTAL);

  // ==========================================
  // 4. DIAGONAL TORSO & RADIANT ARCANE CORE
  // ==========================================
  // Torso sections rising toward -Z and +Y
  fillEllipsoid(12.5, 22.0, 13.5, 3.1, 3.0, 2.9, T_STONE);
  fillEllipsoid(12.5, 25.5, 11.5, 3.5, 3.3, 3.1, T_STONE);
  fillEllipsoid(12.5, 28.5, 9.5, 3.7, 3.6, 3.3, T_STONE);

  // Arcane Heart Core embedded in chest
  fillEllipsoid(12.5, 27.5, 9.8, 1.8, 1.8, 1.8, M_CRYSTAL);
  fillEllipsoid(12.5, 27.5, 9.8, 1.0, 1.0, 1.0, M_LANTERN);

  // Gilded Pectoral Emblem facing North (-Z)
  setBlock(12, 28, 6, M_GOLD);
  setBlock(13, 28, 6, M_GOLD);
  setBlock(12.5, 29, 6, M_LANTERN);
  setBlock(12.5, 27, 6, M_CRYSTAL);

  // ==========================================
  // 5. REARING FORELEGS (MID-AIR STRIKE)
  // ==========================================
  // Left Foreleg (striking forward-down)
  fillCapsule(9.0, 28.0, 9.5, 7.5, 26.0, 6.0, 1.6, 1.3, T_STONE);
  fillCapsule(7.5, 26.0, 6.0, 7.0, 23.0, 3.5, 1.3, 1.1, T_STONE);
  fillCapsule(7.0, 23.0, 3.5, 6.5, 22.0, 2.5, 1.2, 1.4, M_GOLD);

  // Right Foreleg (poised high in defiant challenge)
  fillCapsule(16.0, 28.0, 9.5, 16.5, 29.5, 5.5, 1.6, 1.3, T_STONE);
  fillCapsule(16.5, 29.5, 5.5, 16.0, 25.5, 4.0, 1.3, 1.1, T_STONE);
  fillCapsule(16.0, 25.5, 4.0, 15.5, 24.5, 3.0, 1.2, 1.4, M_GOLD);

  // ==========================================
  // 6. ARCHED EQUINE NECK & THROAT
  // ==========================================
  fillEllipsoid(12.5, 30.0, 8.5, 2.7, 2.4, 2.5, T_STONE);
  fillEllipsoid(12.5, 32.5, 7.2, 2.4, 2.2, 2.2, T_STONE);
  fillEllipsoid(12.5, 34.5, 6.0, 2.0, 2.0, 2.0, T_STONE);
  fillEllipsoid(12.5, 36.0, 5.2, 1.8, 1.8, 1.8, T_STONE);

  // ==========================================
  // 7. HEAD, NOBLE MUZZLE & RADIANT EYES
  // ==========================================
  // Skull & Cheeks
  fillEllipsoid(12.5, 36.0, 4.8, 1.8, 1.6, 1.8, T_STONE);
  // Bridge of Nose & Muzzle pointing straight North (-Z)
  fillEllipsoid(12.5, 35.5, 3.5, 1.4, 1.3, 1.4, T_STONE);
  fillEllipsoid(12.5, 34.5, 2.2, 1.2, 1.1, 1.2, T_STONE);
  fillEllipsoid(12.5, 34.0, 3.5, 1.3, 1.0, 1.2, T_STONE);

  // Arcane Crystalline Eyes gazing toward pirate island
  setBlock(10.5, 36.0, 4.2, M_LANTERN);
  setBlock(14.5, 36.0, 4.2, M_LANTERN);

  // Alert Equine Ears
  fillCapsule(10.5, 37.5, 5.5, 9.5, 40.0, 6.0, 0.7, 0.3, T_STONE);
  fillCapsule(14.5, 37.5, 5.5, 15.5, 40.0, 6.0, 0.7, 0.3, T_STONE);
  setBlock(10.2, 38.5, 5.5, M_CRYSTAL);
  setBlock(14.8, 38.5, 5.5, M_CRYSTAL);

  // ==========================================
  // 8. THE GREAT CELESTIAL ALICORN HORN
  // ==========================================
  // Spiraling crystal and gold horn pointing forward and up toward -Z
  fillCapsule(12.5, 37.5, 3.2, 12.5, 38.2, 2.5, 1.2, 1.0, M_GOLD);
  fillCapsule(12.5, 38.2, 2.5, 12.5, 39.2, 1.8, 1.0, 0.8, M_LANTERN);
  fillCapsule(12.5, 39.2, 1.8, 12.5, 40.2, 1.2, 0.8, 0.6, M_CRYSTAL);
  fillCapsule(12.5, 40.2, 1.2, 12.5, 41.2, 0.6, 0.6, 0.4, T_STONE);
  setBlock(12.5, 42.0, 0.2, M_ROD_NORTH);

  // ==========================================
  // 9. FLOWING CRYSTALLINE MANE
  // ==========================================
  // Forelock
  fillCapsule(12.5, 38.0, 4.5, 12.5, 37.0, 3.8, 0.6, 0.4, M_CRYSTAL);

  // Billowing mane strands swept back by sea winds
  const maneStrands = [
    { p0: { x: 12.5, y: 37.5, z: 6.5 }, p1: { x: 11.5, y: 36.5, z: 7.5 }, p2: { x: 11.0, y: 34.0, z: 8.5 }, mat: M_CRYSTAL },
    { p0: { x: 12.5, y: 35.5, z: 7.5 }, p1: { x: 13.5, y: 34.5, z: 8.5 }, p2: { x: 14.0, y: 32.0, z: 9.5 }, mat: M_LANTERN },
    { p0: { x: 12.5, y: 33.5, z: 8.5 }, p1: { x: 12.0, y: 31.5, z: 10.0 }, p2: { x: 11.5, y: 29.0, z: 11.0 }, mat: M_CRYSTAL },
    { p0: { x: 12.5, y: 31.0, z: 9.5 }, p1: { x: 13.0, y: 29.0, z: 11.0 }, p2: { x: 12.5, y: 27.0, z: 12.0 }, mat: M_CRYSTAL }
  ];
  for (const s of maneStrands) {
    fillCapsule(s.p0.x, s.p0.y, s.p0.z, s.p1.x, s.p1.y, s.p1.z, 0.8, 0.7, s.mat);
    fillCapsule(s.p1.x, s.p1.y, s.p1.z, s.p2.x, s.p2.y, s.p2.z, 0.7, 0.4, s.mat);
  }

  // ==========================================
  // 10. CELESTIAL CRYSTALLINE WINGS
  // ==========================================
  // Left Wing (X: 10 down to 2)
  const lS0 = { x: 10.0, y: 28.5, z: 10.5 };
  const lS1 = { x: 7.5,  y: 32.0, z: 11.5 };
  const lS2 = { x: 4.5,  y: 36.0, z: 13.0 };
  const lS3 = { x: 2.0,  y: 40.0, z: 14.5 };

  const lF0 = { x: 7.0,  y: 23.5, z: 13.5 };
  const lF1 = { x: 5.0,  y: 26.0, z: 15.0 };
  const lF2 = { x: 3.0,  y: 31.0, z: 16.0 };
  const lF3 = { x: 2.5,  y: 37.0, z: 15.0 };

  // Wing spars
  fillCapsule(lS0.x, lS0.y, lS0.z, lS1.x, lS1.y, lS1.z, 1.5, 1.3, T_STONE);
  fillCapsule(lS1.x, lS1.y, lS1.z, lS2.x, lS2.y, lS2.z, 1.3, 1.1, M_CRYSTAL);
  fillCapsule(lS2.x, lS2.y, lS2.z, lS3.x, lS3.y, lS3.z, 1.1, 0.8, M_CRYSTAL);

  // Wing membranes
  fillQuad(lS0, lS1, lF1, lF0, T_STONE);
  fillQuad(lS1, lS2, lF2, lF1, M_CRYSTAL);
  fillQuad(lS2, lS3, lF3, lF2, M_LANTERN);

  // Feather trailing ribs
  fillCapsule(lS1.x, lS1.y, lS1.z, lF1.x, lF1.y, lF1.z, 0.9, 0.5, M_CRYSTAL);
  fillCapsule(lS2.x, lS2.y, lS2.z, lF2.x, lF2.y, lF2.z, 0.9, 0.5, M_LANTERN);
  fillCapsule(lS3.x, lS3.y, lS3.z, lF3.x, lF3.y, lF3.z, 0.8, 0.4, M_CRYSTAL);

  // Right Wing (Mirror on X: 15 up to 23)
  const rS0 = { x: 15.0, y: 28.5, z: 10.5 };
  const rS1 = { x: 17.5, y: 32.0, z: 11.5 };
  const rS2 = { x: 20.5, y: 36.0, z: 13.0 };
  const rS3 = { x: 23.0, y: 40.0, z: 14.5 };

  const rF0 = { x: 18.0, y: 23.5, z: 13.5 };
  const rF1 = { x: 20.0, y: 26.0, z: 15.0 };
  const rF2 = { x: 22.0, y: 31.0, z: 16.0 };
  const rF3 = { x: 22.5, y: 37.0, z: 15.0 };

  // Wing spars
  fillCapsule(rS0.x, rS0.y, rS0.z, rS1.x, rS1.y, rS1.z, 1.5, 1.3, T_STONE);
  fillCapsule(rS1.x, rS1.y, rS1.z, rS2.x, rS2.y, rS2.z, 1.3, 1.1, M_CRYSTAL);
  fillCapsule(rS2.x, rS2.y, rS2.z, rS3.x, rS3.y, rS3.z, 1.1, 0.8, M_CRYSTAL);

  // Wing membranes
  fillQuad(rS0, rS1, rF1, rF0, T_STONE);
  fillQuad(rS1, rS2, rF2, rF1, M_CRYSTAL);
  fillQuad(rS2, rS3, rF3, rF2, M_LANTERN);

  // Feather trailing ribs
  fillCapsule(rS1.x, rS1.y, rS1.z, rF1.x, rF1.y, rF1.z, 0.9, 0.5, M_CRYSTAL);
  fillCapsule(rS2.x, rS2.y, rS2.z, rF2.x, rF2.y, rF2.z, 0.9, 0.5, M_LANTERN);
  fillCapsule(rS3.x, rS3.y, rS3.z, rF3.x, rF3.y, rF3.z, 0.8, 0.4, M_CRYSTAL);

  // Wingtip focus crystals
  setBlock(2.0, 40.0, 14.5, M_LANTERN);
  setBlock(23.0, 40.0, 14.5, M_LANTERN);
  setBlock(2.0, 41.0, 14.5, M_ROD_UP);
  setBlock(23.0, 41.0, 14.5, M_ROD_UP);

  // ==========================================
  // 11. EMIT ALL BLOCKS DETERMINISTICALLY
  // ==========================================
  for (let y = 0; y < H; y++) {
    for (let z = 0; z < D; z++) {
      for (let x = 0; x < W; x++) {
        const key = (x << 16) | (y << 8) | z;
        const block = grid.get(key);
        if (block) {
          api.set(x, y, z, block);
        }
      }
    }
  }

  return {
    name: "Unicorn Colossus",
    seatY: seatPlaneY,
    anchors: {
      front: [13, seatPlaneY, 0],
      base: [13, seatPlaneY, 13],
      horn_tip: [13, 42, 0]
    }
  };
}

corsair_dreadnought.source:
export const envelope = [21, 40, 56];

export default function build(api) {
  const [W, H, D] = api.size;
  const cx = Math.floor(W / 2); // 10

  // Palette aliases from theme
  const woodPlanks = api.theme.wood.planks;
  const woodLog = api.theme.wood.log;
  const woodStripped = api.theme.wood.stripped || api.theme.wood.log;
  const woodStairs = api.theme.wood.stairs;
  const woodSlab = api.theme.wood.slab;
  const woodFence = api.theme.wood.fence;
  const woodTrapdoor = api.theme.wood.trapdoor;
  const woodDoor = api.theme.wood.door;

  // Pirate dreadnought specific materials
  const cannonDispenser = "minecraft:dispenser";
  const cannonBarrel = "minecraft:polished_blackstone_wall";
  const cannonCarriage = "minecraft:polished_blackstone_slab";
  const sailBlack = "minecraft:black_wool";
  const sailRed = "minecraft:red_wool";
  const sailSkull = "minecraft:white_wool";
  const ironChain = "minecraft:chain";
  const ironBar = "minecraft:iron_bars";
  const lanternNorm = "minecraft:lantern[hanging=false]";
  const lanternHanging = "minecraft:lantern[hanging=true]";
  const soulLanternHanging = "minecraft:soul_lantern[hanging=true]";
  const anchorBlock = "minecraft:anvil[facing=north]";

  // Voxel storage buffer for deterministic emission
  const buffer = new Map();
  function put(x, y, z, block) {
    if (x < 0 || x >= W || y < 0 || y >= H || z < 0 || z >= D) return;
    const key = x + y * 100 + z * 10000;
    buffer.set(key, { x, y, z, block });
  }

  function get(x, y, z) {
    const key = x + y * 100 + z * 10000;
    const item = buffer.get(key);
    return item ? item.block : null;
  }

  // --- 1. Hull Geometry Functions ---
  function getHalfWidth(y, z) {
    if (z < 6 || z > 52) return 0;
    const u = (z - 6) / 46.0; // 0.0 at bow, 1.0 at stern

    // Max beam at waterline
    let maxW;
    if (u < 0.25) {
      maxW = 0.8 + 4.0 * Math.sqrt(u / 0.25);
    } else if (u <= 0.72) {
      maxW = 4.8 + 0.3 * Math.sin(((u - 0.25) / 0.47) * Math.PI);
    } else {
      const su = (u - 0.72) / 0.28;
      maxW = 5.0 - 1.4 * su * su;
    }

    // Keel and sheer lines
    const yKeel = (u < 0.1) ? 3 : 2;
    let ySheer = 14;
    if (u < 0.22) {
      ySheer = 17; // forecastle
    } else if (u > 0.85) {
      ySheer = 20; // poop deck
    } else if (u > 0.65) {
      ySheer = 17; // quarterdeck
    }

    if (y < yKeel || y > ySheer) return 0;

    // Tumblehome cross-section
    const hNorm = (y - yKeel) / Math.max(1, ySheer - yKeel);
    let w;
    if (hNorm < 0.35) {
      w = maxW * Math.sqrt(hNorm / 0.35);
    } else if (hNorm <= 0.75) {
      w = maxW * (1.0 - 0.12 * ((hNorm - 0.35) / 0.4));
    } else {
      if (u > 0.65) {
        w = maxW * 0.9 + 0.4 * (hNorm - 0.75);
      } else {
        w = maxW * 0.85;
      }
    }
    return w;
  }

  // --- 2. Build Keel, Hull Shell and Foundation ---
  for (let z = 6; z <= 52; z++) {
    const u = (z - 6) / 46.0;
    const yKeel = (u < 0.1) ? 3 : 2;
    let ySheer = 14;
    if (u < 0.22) ySheer = 17;
    else if (u > 0.85) ySheer = 20;
    else if (u > 0.65) ySheer = 17;

    // Seabed footing along the keel line
    const groundY = api.heightAt(cx, z);
    for (let y = Math.min(0, groundY); y <= yKeel + 1; y++) {
      put(cx, y, z, woodLog);
    }

    // Transom stern wall at z=52
    if (z === 52) {
      for (let y = yKeel; y <= ySheer; y++) {
        const hw = Math.round(getHalfWidth(y, z));
        for (let x = cx - hw; x <= cx + hw; x++) {
          put(x, y, z, (y === 14 || y === 17) ? ironBar : woodPlanks);
        }
      }
    }

    // Hull cross-sections
    for (let y = yKeel; y <= ySheer; y++) {
      const hwExact = getHalfWidth(y, z);
      const hw = Math.round(hwExact);
      if (hw <= 0) continue;

      const minX = cx - hw;
      const maxX = cx + hw;

      // Outer planking
      put(minX, y, z, woodPlanks);
      put(maxX, y, z, woodPlanks);

      // Keel spine
      if (y === yKeel) {
        put(cx, y, z, woodLog);
      }
    }
  }

  // --- 3. Decks (Floors & Ceilings) ---
  // Hold Floor (y=3), Lower Gun Deck (y=6), Middle Deck (y=9), Upper/Main Deck (y=12),
  // Forecastle Deck (y=15), Quarterdeck (y=15), Poop Deck (y=18)
  for (let z = 7; z <= 51; z++) {
    const u = (z - 6) / 46.0;

    // Hold floor (y=3)
    if (z >= 12 && z <= 48) {
      const hw = Math.floor(getHalfWidth(3, z));
      for (let x = cx - hw + 1; x <= cx + hw - 1; x++) {
        put(x, 3, z, woodPlanks);
      }
    }

    // Lower gun deck (y=6)
    if (z >= 10 && z <= 50) {
      const hw = Math.floor(getHalfWidth(6, z));
      for (let x = cx - hw + 1; x <= cx + hw - 1; x++) {
        put(x, 6, z, (x === cx) ? woodStripped : woodPlanks);
      }
    }

    // Middle gun deck (y=9)
    if (z >= 9 && z <= 51) {
      const hw = Math.floor(getHalfWidth(9, z));
      for (let x = cx - hw + 1; x <= cx + hw - 1; x++) {
        put(x, 9, z, (x === cx) ? woodStripped : woodPlanks);
      }
    }

    // Main weather deck (y=12)
    if (z >= 9 && z <= 51) {
      const hw = Math.floor(getHalfWidth(12, z));
      for (let x = cx - hw + 1; x <= cx + hw - 1; x++) {
        put(x, 12, z, (x === cx) ? woodStripped : woodPlanks);
      }
    }

    // Forecastle deck (y=15)
    if (u < 0.22 && z >= 8) {
      const hw = Math.floor(getHalfWidth(15, z));
      for (let x = cx - hw + 1; x <= cx + hw - 1; x++) {
        put(x, 15, z, woodPlanks);
      }
    }

    // Quarterdeck (y=15)
    if (u >= 0.65 && u < 0.85) {
      const hw = Math.floor(getHalfWidth(15, z));
      for (let x = cx - hw + 1; x <= cx + hw - 1; x++) {
        put(x, 15, z, woodPlanks);
      }
    }

    // Poop deck (y=18)
    if (u >= 0.85 && z <= 51) {
      const hw = Math.floor(getHalfWidth(18, z));
      for (let x = cx - hw + 1; x <= cx + hw - 1; x++) {
        put(x, 18, z, woodPlanks);
      }
    }
  }

  // Bulkheads / Cabin Walls
  for (let x = cx - 4; x <= cx + 4; x++) {
    for (let y = 13; y <= 15; y++) {
      if (Math.abs(x - cx) <= 3) {
        put(x, y, 36, (x === cx && y === 13) ? woodDoor : woodPlanks);
      }
    }
    for (let y = 16; y <= 18; y++) {
      if (Math.abs(x - cx) <= 3) {
        put(x, y, 44, (x === cx && y === 16) ? woodDoor : woodPlanks);
      }
    }
    // Forecastle bulkhead
    for (let y = 13; y <= 15; y++) {
      if (Math.abs(x - cx) <= 3) {
        put(x, y, 16, (x === cx && y === 13) ? woodDoor : woodPlanks);
      }
    }
  }

  // --- 4. Three Tiers of Cannons & Broadside Batteries ---
  // Tier 1: Lower Gun Deck (y = 7..8)
  const tier1Z = [18, 22, 26, 30, 34, 38, 42];
  for (const z of tier1Z) {
    const hw = Math.round(getHalfWidth(7, z));
    // Port
    const px = cx - hw;
    put(px + 1, 7, z, `${cannonDispenser}[facing=west]`);
    put(px, 7, z, cannonBarrel);
    put(px + 2, 7, z, cannonCarriage);
    put(px, 8, z, `${woodTrapdoor}[facing=west,half=top,open=true]`);

    // Starboard
    const sx = cx + hw;
    put(sx - 1, 7, z, `${cannonDispenser}[facing=east]`);
    put(sx, 7, z, cannonBarrel);
    put(sx - 2, 7, z, cannonCarriage);
    put(sx, 8, z, `${woodTrapdoor}[facing=east,half=top,open=true]`);
  }

  // Tier 2: Middle Gun Deck (y = 10..11)
  const tier2Z = [16, 20, 24, 28, 32, 36, 40, 44];
  for (const z of tier2Z) {
    const hw = Math.round(getHalfWidth(10, z));
    // Port
    const px = cx - hw;
    put(px + 1, 10, z, `${cannonDispenser}[facing=west]`);
    put(px, 10, z, cannonBarrel);
    put(px + 2, 10, z, cannonCarriage);
    put(px, 11, z, `${woodTrapdoor}[facing=west,half=top,open=true]`);

    // Starboard
    const sx = cx + hw;
    put(sx - 1, 10, z, `${cannonDispenser}[facing=east]`);
    put(sx, 10, z, cannonBarrel);
    put(sx - 2, 10, z, cannonCarriage);
    put(sx, 11, z, `${woodTrapdoor}[facing=east,half=top,open=true]`);
  }

  // Tier 3: Weather Deck Broadside & Rails (y = 13..14)
  const tier3Z = [18, 22, 26, 30, 34];
  for (const z of tier3Z) {
    const hw = Math.round(getHalfWidth(13, z));
    // Port
    const px = cx - hw;
    put(px + 1, 13, z, `${cannonDispenser}[facing=west]`);
    put(px, 13, z, cannonBarrel);
    put(px + 2, 13, z, cannonCarriage);

    // Starboard
    const sx = cx + hw;
    put(sx - 1, 13, z, `${cannonDispenser}[facing=east]`);
    put(sx, 13, z, cannonBarrel);
    put(sx - 2, 13, z, cannonCarriage);
  }

  // Bow Chasers (Aimed North towards Unicorn Island)
  put(cx - 1, 16, 8, `${cannonDispenser}[facing=north]`);
  put(cx - 1, 16, 7, cannonBarrel);
  put(cx + 1, 16, 8, `${cannonDispenser}[facing=north]`);
  put(cx + 1, 16, 7, cannonBarrel);

  // Stern Chasers (Aimed South)
  put(cx - 1, 13, 51, `${cannonDispenser}[facing=south]`);
  put(cx - 1, 13, 52, cannonBarrel);
  put(cx + 1, 13, 51, `${cannonDispenser}[facing=south]`);
  put(cx + 1, 13, 52, cannonBarrel);

  // --- 5. Bowsprit, Beakhead & Prow ---
  // Cutwater stem
  for (let z = 3; z <= 6; z++) {
    const yCut = 14 - (6 - z);
    for (let y = 4; y <= yCut; y++) {
      put(cx, y, z, woodLog);
    }
  }

  // Beakhead platform
  for (let z = 3; z <= 7; z++) {
    put(cx - 1, 13, z, woodPlanks);
    put(cx, 13, z, woodStripped);
    put(cx + 1, 13, z, woodPlanks);
    if (z <= 5) {
      put(cx - 1, 14, z, woodFence);
      put(cx + 1, 14, z, woodFence);
    }
  }

  // Dread Figurehead (Gilded Beast & Bone Relic)
  put(cx, 14, 2, "minecraft:gilded_blackstone");
  put(cx, 15, 2, "minecraft:bone_block[axis=y]");
  put(cx - 1, 14, 2, "minecraft:dark_oak_stairs[facing=east,half=top]");
  put(cx + 1, 14, 2, "minecraft:dark_oak_stairs[facing=west,half=top]");

  // Bowsprit spar reaching to local North (z=0)
  const bowspritPoints = [
    [cx, 15, 7], [cx, 16, 5], [cx, 17, 3], [cx, 18, 1], [cx, 19, 0]
  ];
  for (const [bx, by, bz] of bowspritPoints) {
    put(bx, by, bz, woodLog);
  }
  put(cx, 16, 4, ironChain);
  put(cx, 17, 2, ironChain);
  put(cx, 18, 0, lanternHanging);

  // Anchors on port & starboard bows
  for (const [ax, az] of [[cx - 4, 10], [cx + 4, 10]]) {
    const groundY = api.heightAt(ax, az);
    for (let y = groundY; y <= 14; y++) {
      put(ax, y, az, ironChain);
    }
    put(ax, groundY, az, anchorBlock);
  }

  // --- 6. Stern Castle & Aft Galleries ---
  // Rudder
  for (let y = 2; y <= 12; y++) {
    put(cx, y, 53, woodPlanks);
    put(cx, y, 54, woodFence);
  }

  // Lower & Upper Stern Balconies (Galleries)
  for (const [galY, galZ] of [[13, 53], [16, 53]]) {
    for (let x = cx - 3; x <= cx + 3; x++) {
      put(x, galY, galZ, woodSlab);
      put(x, galY + 1, galZ, woodFence);
    }
    put(cx - 3, galY + 1, galZ, soulLanternHanging);
    put(cx + 3, galY + 1, galZ, soulLanternHanging);
    put(cx, galY + 1, galZ, lanternHanging);
  }

  // Ship's Wheel (Helm) on Quarterdeck
  put(cx, 16, 43, woodPlanks);
  put(cx, 17, 43, "minecraft:dark_oak_fence");
  put(cx, 17, 42, "minecraft:grindstone[facing=north]");

  // Ship's Belfry (Forecastle Bell)
  put(cx, 16, 15, woodFence);
  put(cx, 17, 15, "minecraft:bell[attachment=ceiling,facing=north]");

  // --- 7. Masts, Crow's Nests, Sails & Rigging ---
  function buildCrowsNest(mastX, mastY, mastZ) {
    for (let x = mastX - 1; x <= mastX + 1; x++) {
      for (let z = mastZ - 1; z <= mastZ + 1; z++) {
        if (x === mastX && z === mastZ) continue;
        put(x, mastY, z, woodPlanks);
        put(x, mastY + 1, z, woodFence);
      }
    }
    put(mastX - 1, mastY + 1, mastZ, lanternHanging);
    put(mastX + 1, mastY + 1, mastZ, lanternHanging);
  }

  // A. FOREMAST (z = 16)
  for (let y = 6; y <= 34; y++) put(cx, y, 16, woodLog);
  buildCrowsNest(cx, 24, 16);

  // Foremast Lower Yard & Billowing Course Sail
  for (let x = cx - 6; x <= cx + 6; x++) put(x, 19, 15, woodSlab);
  for (let x = cx - 5; x <= cx + 5; x++) {
    const isRed = (Math.abs(x - cx) === 2 || Math.abs(x - cx) === 4);
    const sailBlock = isRed ? sailRed : sailBlack;
    put(x, 18, 15, sailBlock);
    put(x, 17, 14, sailBlock);
    put(x, 16, 14, sailBlock);
    put(x, 15, 15, sailBlock);
  }

  // Foremast Topsail Yard & Sail
  for (let x = cx - 4; x <= cx + 4; x++) put(x, 27, 15, woodSlab);
  for (let x = cx - 3; x <= cx + 3; x++) {
    const sailBlock = (Math.abs(x - cx) === 2) ? sailRed : sailBlack;
    put(x, 26, 15, sailBlock);
    put(x, 25, 14, sailBlock);
    put(x, 24, 15, sailBlock);
  }

  // Foremast Topgallant Yard & Sail
  for (let x = cx - 3; x <= cx + 3; x++) put(x, 32, 15, woodSlab);
  for (let x = cx - 2; x <= cx + 2; x++) {
    put(x, 31, 15, sailBlack);
    put(x, 30, 15, sailBlack);
  }

  // B. MAINMAST (z = 28) - Dread Corsair Flagship Center
  for (let y = 6; y <= 38; y++) put(cx, y, 28, woodLog);
  buildCrowsNest(cx, 26, 28);

  // Main Lower Yard & Mainsail with Skull Emblem
  for (let x = cx - 7; x <= cx + 7; x++) put(x, 20, 27, woodSlab);
  for (let x = cx - 6; x <= cx + 6; x++) {
    for (let y = 15; y <= 19; y++) {
      const zOffset = (y === 17 || y === 18) ? 26 : 27;
      let block = sailBlack;

      // Dread Skull motif in center
      const dx = Math.abs(x - cx);
      if (y === 18 && dx <= 1) block = sailSkull;
      else if (y === 17 && dx <= 2) block = sailSkull;
      else if (y === 16 && dx === 1) block = sailSkull; // teeth
      else if (dx === 4 || dx === 5) block = sailRed;   // red borders

      put(x, y, zOffset, block);
    }
  }

  // Main Topsail Yard & Sail
  for (let x = cx - 5; x <= cx + 5; x++) put(x, 29, 27, woodSlab);
  for (let x = cx - 4; x <= cx + 4; x++) {
    for (let y = 25; y <= 28; y++) {
      const zOffset = (y === 26 || y === 27) ? 26 : 27;
      const block = (Math.abs(x - cx) === 3) ? sailRed : sailBlack;
      put(x, y, zOffset, block);
    }
  }

  // Main Topgallant Yard & Sail
  for (let x = cx - 3; x <= cx + 3; x++) put(x, 35, 27, woodSlab);
  for (let x = cx - 2; x <= cx + 2; x++) {
    put(x, 34, 27, sailBlack);
    put(x, 33, 27, sailBlack);
    put(x, 32, 27, sailBlack);
  }

  // Mainmast Jolly Roger Pirate Pennant (y=38..39)
  put(cx, 39, 28, "minecraft:black_wool");
  put(cx, 39, 29, "minecraft:black_wool");
  put(cx, 39, 30, "minecraft:white_wool");
  put(cx, 38, 30, "minecraft:black_wool");
  put(cx, 39, 31, "minecraft:black_wool");

  // C. MIZZENMAST (z = 42)
  for (let y = 12; y <= 33; y++) put(cx, y, 42, woodLog);
  buildCrowsNest(cx, 23, 42);

  // Lateen / Spanker Yard angled aft
  for (let step = 0; step <= 8; step++) {
    const yZ = 18 + step;
    const zZ = 38 + step;
    put(cx, yZ, zZ, woodLog);
    // Billowing spanker sail
    if (step >= 1 && step <= 7) {
      for (let sy = 16; sy < yZ; sy++) {
        put(cx, sy, zZ, (step % 2 === 0) ? sailRed : sailBlack);
      }
    }
  }

  // Mizzen Topsail
  for (let x = cx - 3; x <= cx + 3; x++) put(x, 28, 41, woodSlab);
  for (let x = cx - 2; x <= cx + 2; x++) {
    put(x, 27, 41, sailBlack);
    put(x, 26, 41, sailBlack);
    put(x, 25, 41, sailBlack);
  }

  // --- 8. Standing Rigging & Shrouds ---
  // Ratlines / shrouds from mast fighting tops to ship channels
  function buildShrouds(mastX, mastY, mastZ, deckY, spanZ) {
    for (let dz = -spanZ; dz <= spanZ; dz += 2) {
      const zPos = mastZ + dz;
      const hw = Math.round(getHalfWidth(deckY, zPos));
      // Port shroud
      put(cx - hw, deckY, zPos, woodFence);
      for (let y = deckY + 1; y <= mastY; y++) {
        const ratio = (y - deckY) / (mastY - deckY);
        const xPos = Math.round((cx - hw) * (1 - ratio) + (mastX - 1) * ratio);
        put(xPos, y, zPos, ironChain);
      }
      // Starboard shroud
      put(cx + hw, deckY, zPos, woodFence);
      for (let y = deckY + 1; y <= mastY; y++) {
        const ratio = (y - deckY) / (mastY - deckY);
        const xPos = Math.round((cx + hw) * (1 - ratio) + (mastX + 1) * ratio);
        put(xPos, y, zPos, ironChain);
      }
    }
  }

  buildShrouds(cx, 24, 16, 15, 2); // Foremast
  buildShrouds(cx, 26, 28, 14, 3); // Mainmast
  buildShrouds(cx, 23, 42, 16, 2); // Mizzenmast

  // Stays between masts along center
  for (let z = 17; z <= 27; z++) {
    const yStay = Math.round(24 + ((z - 16) / 12) * (26 - 24));
    put(cx, yStay, z, ironChain);
  }
  for (let z = 29; z <= 41; z++) {
    const yStay = Math.round(26 - ((z - 28) / 14) * (26 - 23));
    put(cx, yStay, z, ironChain);
  }

  // --- 9. Deck Railings & Details ---
  // Waist railings
  for (let z = 16; z <= 37; z++) {
    const hw = Math.round(getHalfWidth(13, z));
    put(cx - hw, 14, z, woodFence);
    put(cx + hw, 14, z, woodFence);
  }

  // Forecastle and Quarterdeck railings
  for (let z = 8; z <= 15; z++) {
    const hw = Math.round(getHalfWidth(16, z));
    put(cx - hw, 17, z, woodFence);
    put(cx + hw, 17, z, woodFence);
  }
  for (let z = 38; z <= 51; z++) {
    const yRail = (z >= 45) ? 20 : 17;
    const hw = Math.round(getHalfWidth(yRail - 1, z));
    put(cx - hw, yRail, z, woodFence);
    put(cx + hw, yRail, z, woodFence);
  }

  // Midships cargo hatch with ladder down to hold
  for (let z = 21; z <= 23; z++) {
    for (let x = cx - 1; x <= cx + 1; x++) {
      put(x, 12, z, `${woodTrapdoor}[facing=north,half=bottom,open=false]`);
    }
  }
  for (let y = 4; y <= 12; y++) {
    put(cx, y, 24, "minecraft:ladder[facing=north]");
  }

  // Flush buffer to api in sorted deterministic order
  const entries = Array.from(buffer.values());
  entries.sort((a, b) => (a.x - b.x) || (a.y - b.y) || (a.z - b.z));
  for (const item of entries) {
    api.set(item.x, item.y, item.z, item.block);
  }

  return {
    name: "Corsair Dreadnought War Galleon",
    seatY: 0,
    anchors: {
      front: [cx, 15, 0],       // Prow & Bowsprit aiming North at Unicorn Island
      helm: [cx, 17, 43],        // Quarterdeck ship's wheel
      cabin: [cx, 14, 46],       // Captain's Great Cabin
      crowsnest: [cx, 26, 28]    // Mainmast Fighting Top
    },
    interiors: [
      {
        // Lower Gun Deck / Powder Magazine
        min: [cx - 2, 7, 18],
        max: [cx + 2, 9, 36],
        kind: "hall"
      },
      {
        // Middle Gun Deck & Crew Quarters
        min: [cx - 2, 10, 18],
        max: [cx + 2, 12, 36],
        kind: "quarters"
      },
      {
        // Captain's Grand Stern Cabin
        min: [cx - 2, 14, 42],
        max: [cx + 2, 16, 50],
        kind: "quarters"
      },
      {
        // Forecastle Officers' Mess
        min: [cx - 2, 13, 9],
        max: [cx + 2, 15, 14],
        kind: "vault"
      }
    ]
  };
}

shore_battery.source:
export const envelope = [11, 9, 11];

export default function build(api) {
  const [sizeX, sizeY, sizeZ] = api.size;
  const rand = () => api.random();
  const instIdx = api.instance?.index ?? 0;

  // 1. Theme palette resolution
  const stonePrimary = api.theme?.stone?.primary ?? "minecraft:stone_bricks";
  const stoneAccent = api.theme?.stone?.accent ?? "minecraft:cobblestone";
  const stoneStairs = api.theme?.stone?.stairs ?? "minecraft:stone_brick_stairs";
  const stoneSlab = api.theme?.stone?.slab ?? "minecraft:stone_brick_slab";

  const woodPlanks = api.theme?.wood?.planks ?? "minecraft:spruce_planks";
  const woodLog = api.theme?.wood?.log ?? "minecraft:spruce_log";
  const woodStripped = api.theme?.wood?.stripped ?? "minecraft:stripped_spruce_log";
  const woodStairs = api.theme?.wood?.stairs ?? "minecraft:spruce_stairs";
  const woodSlab = api.theme?.wood?.slab ?? "minecraft:spruce_slab";
  const woodFence = api.theme?.wood?.fence ?? "minecraft:spruce_fence";

  const groundPlinth = api.theme?.ground?.plinth ?? "minecraft:cobblestone";
  const groundPavement = api.theme?.ground?.pavement ?? "minecraft:stone_bricks";
  const groundRevetment = api.theme?.ground?.revetment ?? "minecraft:packed_mud";
  const groundBank = api.theme?.ground?.bank ?? "minecraft:mud_bricks";
  const groundSlab = api.theme?.ground?.slab ?? stoneSlab;

  // State formatting helpers (safely stripping any existing brackets)
  function cleanId(blockStr) {
    if (!blockStr) return "minecraft:stone";
    return blockStr.split("[")[0];
  }

  function formatStairs(blockStr, facing, half = "bottom", shape = "straight") {
    return `${cleanId(blockStr)}[facing=${facing},half=${half},shape=${shape}]`;
  }

  function formatSlab(blockStr, type = "bottom") {
    return `${cleanId(blockStr)}[type=${type}]`;
  }

  function formatLog(blockStr, axis = "y") {
    return `${cleanId(blockStr)}[axis=${axis}]`;
  }

  // 2. Instance variations
  const archetype = instIdx % 4; // 0: Lean-to Magazine, 1: Signal Mast, 2: Stone Casemate, 3: Derrick Crane
  const brassTier = (instIdx + Math.floor(rand() * 2)) % 5;

  let cannonMain, cannonSlab, cannonRing;
  if (brassTier === 0) {
    cannonMain = "minecraft:cut_copper";
    cannonSlab = "minecraft:cut_copper_slab";
    cannonRing = "minecraft:copper_block";
  } else if (brassTier === 1) {
    cannonMain = "minecraft:exposed_cut_copper";
    cannonSlab = "minecraft:exposed_cut_copper_slab";
    cannonRing = "minecraft:exposed_copper";
  } else if (brassTier === 2) {
    cannonMain = "minecraft:weathered_cut_copper";
    cannonSlab = "minecraft:weathered_cut_copper_slab";
    cannonRing = "minecraft:weathered_copper";
  } else if (brassTier === 3) {
    cannonMain = "minecraft:oxidized_cut_copper";
    cannonSlab = "minecraft:oxidized_cut_copper_slab";
    cannonRing = "minecraft:oxidized_copper";
  } else {
    cannonMain = "minecraft:polished_deepslate";
    cannonSlab = "minecraft:polished_deepslate_slab";
    cannonRing = "minecraft:cut_copper";
  }

  // Aim traverse: -1 = NW (left), 0 = N (center), 1 = NE (right)
  const aimTraverse = ((instIdx * 2 + 1) % 3) - 1;

  // 3. Grid buffer for deterministic assembly & solid connectivity
  const grid = Array.from({ length: sizeX }, () =>
    Array.from({ length: sizeY }, () =>
      new Array(sizeZ).fill(null)
    )
  );

  function put(x, y, z, block) {
    if (x >= 0 && x < sizeX && y >= 0 && y < sizeY && z >= 0 && z < sizeZ && block) {
      grid[x][y][z] = block;
    }
  }

  // --- COURSE 0: Heavy Foundation Plinth (y = 0) ---
  for (let x = 0; x < 11; x++) {
    for (let z = 0; z < 11; z++) {
      const isCorner = (x === 0 || x === 10) && (z === 0 || z === 10);
      if (!isCorner) {
        const mat = rand() < 0.35 ? stoneAccent : (rand() < 0.2 ? groundPlinth : stonePrimary);
        put(x, 0, z, mat);
      }
    }
  }

  // --- COURSE 1: Fortified Gun Deck & Battery Floor (y = 1) ---
  for (let x = 0; x < 11; x++) {
    for (let z = 0; z < 11; z++) {
      const isCorner = (x === 0 || x === 10) && (z === 0 || z === 10);
      if (!isCorner) {
        const isEdge = (x === 0 || x === 10 || z === 0 || z === 10 ||
                        ((x === 1 || x === 9) && (z === 1 || z === 9)));
        if (isEdge) {
          put(x, 1, z, rand() < 0.4 ? stoneAccent : stonePrimary);
        } else if (x >= 4 && x <= 6 && z >= 2 && z <= 7) {
          // Cannon recoil track
          put(x, 1, z, rand() < 0.3 ? woodStripped : woodPlanks);
        } else {
          put(x, 1, z, rand() < 0.5 ? woodPlanks : groundPavement);
        }
      }
    }
  }
  // Access step
  put(5, 1, 10, formatStairs(stoneStairs, "north"));

  // --- COURSE 2: Sandbag Revetments, Parapets & Gun Carriage (y = 2) ---
  // Front embrasure sill and embrasure wings
  put(4, 2, 1, formatStairs(stoneStairs, "east"));
  put(5, 2, 1, formatSlab(stoneSlab, "bottom"));
  put(6, 2, 1, formatStairs(stoneStairs, "west"));

  put(1, 2, 1, groundRevetment);
  put(2, 2, 1, groundRevetment);
  put(3, 2, 1, groundBank);
  put(7, 2, 1, groundBank);
  put(8, 2, 1, groundRevetment);
  put(9, 2, 1, groundRevetment);

  for (let x = 1; x <= 9; x++) {
    if (x < 4 || x > 6) {
      put(x, 2, 2, x % 2 === 0 ? groundBank : groundRevetment);
    }
  }

  // Flank earthwork bastions (X = 1..2 and X = 8..9, Z = 3..8)
  for (let z = 3; z <= 8; z++) {
    put(1, 2, z, z % 2 === 0 ? formatLog(woodLog, "y") : stonePrimary);
    put(2, 2, z, rand() < 0.5 ? groundRevetment : groundBank);
    put(8, 2, z, rand() < 0.5 ? groundBank : groundRevetment);
    put(9, 2, z, z % 2 === 0 ? formatLog(woodLog, "y") : stonePrimary);
  }

  // Rear rampart retaining wall
  put(3, 2, 8, stonePrimary);
  put(4, 2, 8, groundRevetment);
  put(5, 2, 8, woodPlanks); // Passage opening
  put(6, 2, 8, groundRevetment);
  put(7, 2, 8, stonePrimary);

  put(3, 2, 9, groundBank);
  put(4, 2, 9, groundBank);
  put(6, 2, 9, groundBank);
  put(7, 2, 9, groundBank);

  // Gun Carriage at y = 2
  if (aimTraverse === 0) {
    put(4, 2, 4, formatStairs(woodStairs, "north", "top"));
    put(6, 2, 4, formatStairs(woodStairs, "north", "top"));
    put(5, 2, 4, formatLog(woodStripped, "x"));
    put(4, 2, 5, formatStairs(woodStairs, "south", "bottom"));
    put(6, 2, 5, formatStairs(woodStairs, "south", "bottom"));
    put(5, 2, 5, woodPlanks);
    put(5, 2, 6, formatSlab(woodSlab, "bottom"));
  } else if (aimTraverse === -1) {
    put(3, 2, 3, formatStairs(woodStairs, "east", "top"));
    put(4, 2, 4, formatLog(woodStripped, "y"));
    put(6, 2, 4, formatStairs(woodStairs, "west", "top"));
    put(5, 2, 5, woodPlanks);
    put(6, 2, 6, formatSlab(woodSlab, "bottom"));
  } else {
    put(4, 2, 4, formatStairs(woodStairs, "east", "top"));
    put(6, 2, 4, formatLog(woodStripped, "y"));
    put(7, 2, 3, formatStairs(woodStairs, "west", "top"));
    put(5, 2, 5, woodPlanks);
    put(4, 2, 6, formatSlab(woodSlab, "bottom"));
  }

  // Powder Kegs, Cannonballs & Sponge Cauldron (y = 2)
  put(3, 2, 4, "minecraft:tnt[unstable=false]");
  put(3, 2, 5, "minecraft:barrel[facing=up,open=false]");
  put(3, 2, 6, "minecraft:tnt[unstable=false]");
  put(7, 2, 4, "minecraft:polished_blackstone");
  put(7, 2, 5, "minecraft:blackstone");
  put(7, 2, 6, "minecraft:polished_blackstone");
  put(3, 2, 3, "minecraft:cauldron");

  // --- COURSE 3: Upper Sandbag Crest & Heavy Brass Cannon (y = 3) ---
  for (let z = 2; z <= 7; z++) {
    put(1, 3, z, z % 2 === 0 ? groundBank : groundRevetment);
    put(9, 3, z, z % 2 === 0 ? groundRevetment : groundBank);
  }
  put(2, 3, 3, formatSlab(stoneSlab, "bottom"));
  put(2, 3, 5, formatSlab(stoneSlab, "bottom"));
  put(2, 3, 7, formatSlab(stoneSlab, "bottom"));
  put(8, 3, 3, formatSlab(stoneSlab, "bottom"));
  put(8, 3, 5, formatSlab(stoneSlab, "bottom"));
  put(8, 3, 7, formatSlab(stoneSlab, "bottom"));

  put(2, 3, 1, groundBank);
  put(3, 3, 1, formatSlab(stoneSlab, "bottom"));
  put(7, 3, 1, formatSlab(stoneSlab, "bottom"));
  put(8, 3, 1, groundBank);

  // Cannon Barrel assembly (y = 3)
  if (aimTraverse === 0) {
    put(5, 3, 6, "minecraft:lever[face=wall,facing=south,powered=false]");
    put(5, 3, 5, cannonMain);
    put(5, 3, 4, cannonRing);
    put(4, 3, 4, "minecraft:tripwire_hook[attached=false,facing=west,powered=false]");
    put(6, 3, 4, "minecraft:tripwire_hook[attached=false,facing=east,powered=false]");
    put(5, 3, 3, cannonMain);
    put(5, 3, 2, cannonRing);
    put(5, 3, 1, cannonMain);
    put(5, 3, 0, formatSlab(cannonSlab, "bottom"));
  } else if (aimTraverse === -1) {
    put(6, 3, 5, cannonMain);
    put(5, 3, 4, cannonRing);
    put(4, 3, 3, cannonMain);
    put(4, 3, 2, cannonMain);
    put(3, 3, 1, cannonMain);
    put(3, 3, 0, formatSlab(cannonSlab, "bottom"));
  } else {
    put(4, 3, 5, cannonMain);
    put(5, 3, 4, cannonRing);
    put(6, 3, 3, cannonMain);
    put(6, 3, 2, cannonMain);
    put(7, 3, 1, cannonMain);
    put(7, 3, 0, formatSlab(cannonSlab, "bottom"));
  }

  // Upper ammunition piles
  put(3, 3, 5, "minecraft:barrel[facing=up,open=false]");
  put(3, 3, 6, "minecraft:tnt[unstable=false]");
  put(7, 3, 5, formatSlab("minecraft:blackstone_slab", "bottom"));

  // --- COURSE 4: Merlons, Parapet Coping & Lanterns (y = 4) ---
  put(1, 4, 3, formatSlab(stoneSlab, "bottom"));
  put(1, 4, 5, formatSlab(stoneSlab, "bottom"));
  put(1, 4, 7, formatSlab(stoneSlab, "bottom"));
  put(9, 4, 3, formatSlab(stoneSlab, "bottom"));
  put(9, 4, 5, formatSlab(stoneSlab, "bottom"));
  put(9, 4, 7, formatSlab(stoneSlab, "bottom"));

  put(1, 4, 2, "minecraft:lantern[hanging=false,waterlogged=false]");
  put(9, 4, 2, "minecraft:lantern[hanging=false,waterlogged=false]");

  if (aimTraverse === 0) {
    put(5, 4, 5, "minecraft:lever[face=floor,facing=north,powered=false]");
    put(5, 4, 4, formatSlab(cannonSlab, "bottom"));
  } else if (aimTraverse === -1) {
    put(6, 4, 5, "minecraft:lever[face=floor,facing=north,powered=false]");
  } else {
    put(4, 4, 5, "minecraft:lever[face=floor,facing=north,powered=false]");
  }

  // --- REAR REDOUBT STRUCTURE BY ARCHETYPE (y = 2 to y = 8) ---
  if (archetype === 0) {
    // Archetype 0: Timber Lean-to Powder Magazine & Shelter
    for (let y = 2; y <= 4; y++) {
      put(3, y, 7, formatLog(woodLog, "y"));
      put(7, y, 7, formatLog(woodLog, "y"));
    }
    for (let y = 2; y <= 5; y++) {
      put(3, y, 9, formatLog(woodLog, "y"));
      put(7, y, 9, formatLog(woodLog, "y"));
    }

    for (let x = 3; x <= 7; x++) {
      put(x, 5, 7, formatLog(woodLog, "x"));
      put(x, 6, 9, formatLog(woodLog, "x"));
    }
    put(3, 5, 8, woodPlanks);
    put(5, 5, 8, woodPlanks);
    put(7, 5, 8, woodPlanks);

    for (let x = 2; x <= 8; x++) {
      put(x, 6, 9, formatStairs(woodStairs, "north", "bottom"));
      put(x, 6, 8, formatSlab(woodSlab, "top"));
      put(x, 5, 7, formatStairs(woodStairs, "north", "bottom"));
    }

    put(5, 7, 9, formatLog(woodLog, "y"));
    put(5, 8, 9, "minecraft:lightning_rod[facing=up,powered=false,waterlogged=false]");

    put(4, 2, 8, "minecraft:barrel[facing=north,open=false]");
    put(6, 2, 8, "minecraft:tnt[unstable=false]");
    put(4, 3, 8, "minecraft:tnt[unstable=false]");
    put(6, 3, 8, "minecraft:barrel[facing=up,open=false]");
    put(5, 4, 8, "minecraft:lantern[hanging=true,waterlogged=false]");

  } else if (archetype === 1) {
    // Archetype 1: Pirate Signal Mast & Battle Pennant
    for (let y = 2; y <= 5; y++) put(3, y, 8, formatLog(woodLog, "y"));
    for (let y = 6; y <= 7; y++) put(3, y, 8, formatLog(woodStripped, "y"));
    put(3, 8, 8, woodFence);

    put(2, 5, 8, woodFence);
    put(4, 5, 8, woodFence);
    put(2, 4, 8, "minecraft:lantern[hanging=true,waterlogged=false]");

    put(4, 7, 8, "minecraft:black_wool");
    put(5, 7, 8, "minecraft:black_wool");
    put(6, 7, 8, "minecraft:red_wool");
    put(4, 6, 8, "minecraft:black_wool");
    put(5, 6, 8, "minecraft:bone_block[axis=y]");
    put(6, 6, 8, "minecraft:black_wool");

    put(7, 2, 7, woodPlanks);
    put(7, 3, 7, "minecraft:lantern[hanging=false,waterlogged=false]");
    put(7, 2, 8, "minecraft:barrel[facing=up,open=false]");
    put(8, 2, 8, "minecraft:tnt[unstable=false]");
    put(8, 3, 8, "minecraft:barrel[facing=north,open=false]");

  } else if (archetype === 2) {
    // Archetype 2: Reinforced Stone Casemate & Ammunition Vault
    for (let y = 2; y <= 4; y++) {
      put(3, y, 8, stonePrimary);
      put(7, y, 8, stonePrimary);
      put(3, y, 9, stonePrimary);
      put(7, y, 9, stonePrimary);
    }

    put(4, 4, 8, formatStairs(stoneStairs, "west", "top"));
    put(5, 4, 8, stonePrimary);
    put(6, 4, 8, formatStairs(stoneStairs, "east", "top"));

    for (let x = 3; x <= 7; x++) {
      put(x, 5, 8, stonePrimary);
      put(x, 5, 9, stonePrimary);
    }
    for (let x = 4; x <= 6; x++) {
      put(x, 6, 8, formatSlab(stoneSlab, "bottom"));
      put(x, 6, 9, formatSlab(stoneSlab, "bottom"));
    }

    put(5, 6, 8, stonePrimary);
    put(5, 7, 8, woodFence);
    put(5, 8, 8, "minecraft:lantern[hanging=false,waterlogged=false]");

    put(4, 2, 8, "minecraft:tnt[unstable=false]");
    put(6, 2, 8, "minecraft:tnt[unstable=false]");
    put(4, 3, 8, "minecraft:barrel[facing=up,open=false]");
    put(6, 3, 8, "minecraft:barrel[facing=up,open=false]");
    put(5, 4, 8, "minecraft:lantern[hanging=true,waterlogged=false]");

  } else {
    // Archetype 3: Heavy Field Derrick Crane & Fortified Platform
    for (let y = 2; y <= 6; y++) put(7, y, 8, formatLog(woodLog, "y"));
    put(7, 7, 8, woodFence);
    put(7, 8, 8, "minecraft:lightning_rod[facing=up,powered=false,waterlogged=false]");

    put(7, 6, 7, formatLog(woodLog, "z"));
    put(7, 6, 6, formatLog(woodLog, "z"));
    put(7, 6, 5, formatLog(woodLog, "z"));
    put(7, 6, 4, woodFence);

    put(7, 5, 4, "minecraft:chain[axis=y,waterlogged=false]");
    put(7, 4, 4, "minecraft:hopper[facing=down,enabled=true]");
    put(7, 5, 9, woodFence);

    put(6, 2, 6, "minecraft:blackstone");
    put(6, 3, 6, formatSlab("minecraft:blackstone_slab", "bottom"));
    put(3, 2, 8, "minecraft:tnt[unstable=false]");
    put(4, 2, 8, "minecraft:barrel[facing=up,open=false]");
    put(3, 3, 8, "minecraft:barrel[facing=north,open=false]");
    put(4, 3, 8, "minecraft:tnt[unstable=false]");
    put(3, 4, 8, woodFence);
    put(3, 5, 8, "minecraft:lantern[hanging=false,waterlogged=false]");
  }

  // --- Gunpowder Scorch Stains on Firing Apron ---
  if (aimTraverse === 0) {
    put(5, 1, 1, "minecraft:blackstone");
    put(5, 1, 2, "minecraft:polished_blackstone");
  } else if (aimTraverse === -1) {
    put(3, 1, 1, "minecraft:blackstone");
    put(4, 1, 2, "minecraft:polished_blackstone");
  } else {
    put(7, 1, 1, "minecraft:blackstone");
    put(6, 1, 2, "minecraft:polished_blackstone");
  }

  // --- CONNECTIVITY FLOOD-FILL & DETERMINISTIC EMISSION ---
  const visited = Array.from({ length: sizeX }, () =>
    Array.from({ length: sizeY }, () =>
      new Uint8Array(sizeZ)
    )
  );

  const queue = [[5, 0, 5]];
  visited[5][0][5] = 1;

  const dxs = [1, -1, 0, 0, 0, 0];
  const dys = [0, 0, 1, -1, 0, 0];
  const dzs = [0, 0, 0, 0, 1, -1];

  let head = 0;
  while (head < queue.length) {
    const [cx, cy, cz] = queue[head++];
    for (let i = 0; i < 6; i++) {
      const nx = cx + dxs[i];
      const ny = cy + dys[i];
      const nz = cz + dzs[i];
      if (
        nx >= 0 && nx < sizeX &&
        ny >= 0 && ny < sizeY &&
        nz >= 0 && nz < sizeZ &&
        !visited[nx][ny][nz] &&
        grid[nx][ny][nz] !== null
      ) {
        visited[nx][ny][nz] = 1;
        queue.push([nx, ny, nz]);
      }
    }
  }

  for (let y = 0; y < sizeY; y++) {
    for (let z = 0; z < sizeZ; z++) {
      for (let x = 0; x < sizeX; x++) {
        if (visited[x][y][z] && grid[x][y][z]) {
          api.set(x, y, z, grid[x][y][z]);
        }
      }
    }
  }

  return {
    name: "shore_battery",
    seatY: 0,
    anchors: {
      front: [5, 3, 0],
      door: [5, 1, 10]
    }
  };
}
